import fs from 'node:fs/promises';
import { chromium } from 'playwright';
const URL='https://www.statesideqm.com/collections/k9-dog-gear?preview_theme_id=158561894555';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const b=await chromium.launch({headless:true});
for(const [name,viewport] of [['desktop',{width:1440,height:1000}],['mobile',{width:390,height:844}]]){
 const c=await b.newContext({viewport}),p=await c.newPage(),errs=[];p.on('pageerror',e=>errs.push(e.message));const r=await p.goto(URL,{waitUntil:'domcontentloaded',timeout:45000});try{await p.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',{timeout:20000})}catch{}
 const started=Date.now();for(const ms of [500,1500,3000,4500,6500,9000,12000]){const wait=started+ms-Date.now();if(wait>0)await sleep(wait);const d=await p.evaluate(()=>{const vis=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0};const desc=e=>({tag:e.tagName,id:e.id||'',cls:String(e.className||'').replace(/\s+/g,' ').trim().slice(0,160),visible:vis(e),insideMain:!!e.closest('#MainContent'),insideResults:!!e.closest('.sq-refine-v3-results'),parentTag:e.parentElement?.tagName||'',parentId:e.parentElement?.id||'',parentCls:String(e.parentElement?.className||'').replace(/\s+/g,' ').trim().slice(0,120),cards:e.querySelectorAll?.('.product-grid__item').length||0,links:e.querySelectorAll?.('a[href*="/products/"]').length||0});return{ready:document.querySelector('#MainContent')?.dataset.sqRefineV3Ready||'',cleanup:document.querySelector('#MainContent')?.dataset.sqRefineV3RootCleanup||'',grids:[...document.querySelectorAll('.product-grid')].map(desc),components:[...document.querySelectorAll('collection-component')].map(desc),results:[...document.querySelectorAll('.sq-refine-v3-results')].map(desc),columns:[...document.querySelectorAll('.sq-collection-products-column')].map(desc),resultsList:[...document.querySelectorAll('#ResultsList')].map(desc),allProductLinks:document.querySelectorAll('#MainContent a[href*="/products/"]').length};});console.log('SAMPLE '+JSON.stringify({name,ms,http:r?.status()||0,errors:errs,data:d}));}
 await fs.mkdir('cert-k9-dog-gear',{recursive:true});await p.screenshot({path:`cert-k9-dog-gear/${name}.png`,fullPage:true});await c.close();
}
await b.close();
